await p.waitForTimeout(1000);
await p.goto('http://127.0.0.1:54569/products');
const row = p.locator('tr[data-sku="P-1349"]');
await row.locator('button.edit').click();
await row.locator('input[aria-label="Price"]').fill('470');
await row.locator('input[aria-label="Stock"]').fill('44');
await row.locator('button.save').click();
await p.waitForTimeout(800);
